var DPR=1, VW=1, VH=1, QUALITY=1;   /* 1 = 高画质, 0 = 流畅 */
var RES_SCALE=1;   /* 自适应渲染倍率：帧率掉了就自动减，帧率够了再慢慢加回来 */
function resize(){
  var w=window.innerWidth||360, h=window.innerHeight||640;
  var maxDpr=(QUALITY?1.75:1.25);
  DPR=Math.min(maxDpr,window.devicePixelRatio||1)*RES_SCALE;
  /* 像素总量封顶：手机 1080×2400 @dpr2 就是 5.8M 像素，必然卡 */
  var maxPix=QUALITY?2.3e6:1.05e6;
  if(w*h*DPR*DPR>maxPix){ DPR=Math.sqrt(maxPix/(w*h)); }
  VW=Math.floor(w*DPR); VH=Math.floor(h*DPR);
  canvas.width=VW; canvas.height=VH;
  canvas.style.width=w+"px"; canvas.style.height=h+"px";
  gl.viewport(0,0,VW,VH);
}
