/* ================= 程序纹理 ================= */
function tileTexture(){
  var s=1024, cv=document.createElement("canvas"); cv.width=s; cv.height=s;
  var x=cv.getContext("2d");
  var n=4, step=s/n, gw=8;           /* 每张 4×4 块砖，砖 ≈39cm */
  /* 底：灰缝颜色 */
  x.fillStyle="#cbd4d3"; x.fillRect(0,0,s,s);
  for(var i=0;i<n;i++) for(var j=0;j<n;j++){
    var px=i*step+gw, py=j*step+gw, w=step-gw*2, h=step-gw*2;
    /* 每块砖基色略有差别 */
    var base=241-j*1+Math.round((Math.random()-0.5)*11);
    /* 釉面：斜向明暗渐变，模拟灯光在砖面上的反光 */
    var grd=x.createLinearGradient(px,py,px+w,py+h);
    grd.addColorStop(0,"rgb("+(base+5)+","+(base+8)+","+(base+7)+")");
    grd.addColorStop(0.42,"rgb("+base+","+(base+3)+","+(base+2)+")");
    grd.addColorStop(1,"rgb("+(base-9)+","+(base-6)+","+(base-5)+")");
    x.fillStyle=grd; x.fillRect(px,py,w,h);
    /* 斜边：上/左受光，下/右倒角 */
    x.fillStyle="rgba(255,255,255,.42)"; x.fillRect(px,py,w,3);
    x.fillStyle="rgba(255,255,255,.22)"; x.fillRect(px,py,3,h);
    x.fillStyle="rgba(104,124,128,.34)"; x.fillRect(px,py+h-4,w,4);
    x.fillStyle="rgba(96,116,120,.30)"; x.fillRect(px+w-4,py,4,h);
    /* 砖内的细微脏污 */
    for(var q=0;q<5;q++){
      var rx=px+Math.random()*w, ry=py+Math.random()*h, rr=6+Math.random()*22;
      var g2=x.createRadialGradient(rx,ry,0,rx,ry,rr);
      g2.addColorStop(0,"rgba(150,168,166,"+(0.05+Math.random()*0.09)+")");
      g2.addColorStop(1,"rgba(150,168,166,0)");
      x.fillStyle=g2; x.beginPath(); x.arc(rx,ry,rr,0,6.3); x.fill();
    }
  }
  /* 灰缝里的深浅不匀 + 一点积水高光 */
  for(var k=0;k<n;k++){
    x.strokeStyle="rgba(140,156,156,.18)"; x.lineWidth=1.0;
    x.beginPath(); x.moveTo(k*step+gw*0.5,0); x.lineTo(k*step+gw*0.5,s); x.stroke();
    x.beginPath(); x.moveTo(0,k*step+gw*0.5); x.lineTo(s,k*step+gw*0.5); x.stroke();
  }
  /* 大块水渍，跨砖，压在灰缝上 */
  for(var q2=0;q2<26;q2++){
    var rx2=Math.random()*s, ry2=Math.random()*s, rr2=26+Math.random()*120;
    var g3=x.createRadialGradient(rx2,ry2,0,rx2,ry2,rr2);
    g3.addColorStop(0,"rgba(158,178,176,"+(0.06+Math.random()*0.10)+")");
    g3.addColorStop(0.6,"rgba(170,190,188,0.03)");
    g3.addColorStop(1,"rgba(170,190,188,0)");
    x.fillStyle=g3; x.beginPath(); x.arc(rx2,ry2,rr2,0,6.3); x.fill();
  }
  return cv;
}
/* 由高度图算法线贴图：灰缝是凹槽，倒角靠模糊做出来 */
function tileHeight(){
  var s=512, cv=document.createElement("canvas"); cv.width=s; cv.height=s;
  var x=cv.getContext("2d");
  var n=4, step=s/n, gw=Math.round(8*s/1024);
  x.fillStyle="#2e2e2e"; x.fillRect(0,0,s,s);          /* 灰缝最低 */
  for(var i=0;i<n;i++) for(var j=0;j<n;j++){
    var px=i*step+gw, py=j*step+gw, w=step-gw*2, h=step-gw*2;
    x.fillStyle="#f2f2f2"; x.fillRect(px,py,w,h);
  }
  /* 用模糊把硬边变成倒角坡度，法线才有立体感 */
  var tmp=cv;
  var cv2=document.createElement("canvas"); cv2.width=s; cv2.height=s;
  var x2=cv2.getContext("2d");
  try{ x2.filter="blur("+Math.max(2,Math.round(3*s/512))+"px)"; }catch(e){}
  x2.drawImage(tmp,0,0);
  return cv2;
}
function normalFromHeight(hcv,strength){
  var w=hcv.width, h=hcv.height;
  var sd=hcv.getContext("2d").getImageData(0,0,w,h).data;
  var cv=document.createElement("canvas"); cv.width=w; cv.height=h;
  var ctx=cv.getContext("2d");
  var img=ctx.createImageData(w,h);
  function V(x,y){ return sd[((y+h)%h*w+(x+w)%w)*4]/255.0; }
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var dx=(V(x+1,y)-V(x-1,y))*0.5;
    var dy=(V(x,y+1)-V(x,y-1))*0.5;
    var nx=-dx*strength, ny=-dy*strength, nz=1.0;
    var l=Math.sqrt(nx*nx+ny*ny+1.0);
    nx/=l; ny/=l; nz/=l;
    var o=(y*w+x)*4;
    img.data[o]  =Math.round((nx*0.5+0.5)*255);
    img.data[o+1]=Math.round((ny*0.5+0.5)*255);
    img.data[o+2]=Math.round((nz*0.5+0.5)*255);
    img.data[o+3]=255;
  }
  ctx.putImageData(img,0,0);
  return cv;
}
function causticTexture(){
  var s=256, cv=document.createElement("canvas"); cv.width=s; cv.height=s;
  var x=cv.getContext("2d");
  x.fillStyle="#000"; x.fillRect(0,0,s,s);
  x.globalCompositeOperation="lighter";
  for(var i=0;i<70;i++){
    var px=Math.random()*s, py=Math.random()*s;
    var r=6+Math.random()*26;
    x.strokeStyle="rgba(180,240,255,"+(0.12+Math.random()*0.3)+")";
    x.lineWidth=1+Math.random()*3;
    x.beginPath();
    x.arc(px,py,r,Math.random()*6.3,Math.random()*6.3+1.6);
    x.stroke();
  }
  x.globalCompositeOperation="source-over";
  return cv;
}
function mkTex(cvs,mip){
  var t=gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D,t);
  gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cvs);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.REPEAT);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.REPEAT);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,mip?gl.LINEAR_MIPMAP_LINEAR:gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
  if(mip){
    gl.generateMipmap(gl.TEXTURE_2D);
    try{
      var anx=gl.getExtension("EXT_texture_filter_anisotropic");
      if(anx){
        var mx=gl.getParameter(anx.MAX_TEXTURE_MAX_ANISOTROPY_EXT);
        gl.texParameterf(gl.TEXTURE_2D,anx.TEXTURE_MAX_ANISOTROPY_EXT,Math.min(8,mx));
      }
    }catch(e){}
  }
  return t;
}
