var PX=0.056;                                  /* 1 皮肤像素 ≈ 5.6cm，32px ≈ 1.8m */
var NETPC={on:false,host:false,room:"",sid:"",ws:null,ok:false,topic:"",players:{},
           lastPose:0,connack:false,helloTimer:null,ka:null,joined:false};
var NETNAME="玩家";
var NET_ROOM=((/[?&]room=([A-Za-z0-9]{4,8})/.exec(QS)||[])[1]||"").toUpperCase();

function pcBytes(n){
  var a=new Uint8Array(n), ok=false;
  try{ if(window.crypto&&crypto.getRandomValues){ crypto.getRandomValues(a); ok=true; } }catch(e){}
  if(!ok){ for(var i=0;i<n;i++) a[i]=Math.floor(Math.random()*256); }
  return a;
}
function pcRand(){
  var a=pcBytes(8), h="";
  for(var i=0;i<8;i++) h+=("0"+a[i].toString(16)).slice(-2);
  return h;
}
function pcCode(){
  var A="ABCDEFGHJKLMNPQRSTUVWXYZ23456789", o="", r=pcBytes(5);
  for(var i=0;i<5;i++) o+=A[r[i]%A.length];
  return o;
}
function pcTopic(c){ return "rtsx67pool/v1/"+String(c).toLowerCase(); }

/* ---------- 皮肤贴图（64×64，canvas 现画） ---------- */
var skinT=null;
function mkSkin(){
  if(skinT) return skinT;
  var C=document.createElement("canvas"); C.width=64; C.height=64;
  var x=C.getContext("2d"); x.imageSmoothingEnabled=false;
  var SK="#C08A63",HAIR="#2E1E12",SH="#2E9EA0",PA="#3A4A9A",Shoe="#3E3E42",DARK="#20171A";
  function r(u,v,w,h,c){ x.fillStyle=c; x.fillRect(u,v,w,h); }
  r(8,8,8,8,SK); r(0,8,8,8,SK); r(16,8,8,8,SK); r(24,8,8,8,SK); r(8,0,8,8,HAIR); r(16,0,8,8,SK);
  r(8,8,8,2,HAIR); r(0,8,8,2,HAIR); r(16,8,8,2,HAIR); r(24,8,8,2,HAIR);
  r(24,8,8,8,HAIR); r(0,8,8,4,HAIR); r(16,8,8,4,HAIR);
  r(11,13,2,1,"#B07850");
  r(10,11,2,1,"#F1EEE6"); r(13,11,2,1,"#F1EEE6");
  r(10,12,1,1,"#3F63B4"); r(14,12,1,1,"#3F63B4");
  r(11,14,2,1,DARK);
  r(20,20,8,12,SH); r(32,20,8,12,SH); r(16,20,4,12,SH); r(28,20,4,12,SH);
  r(20,16,8,4,SH); r(28,16,8,4,SH); r(22,20,4,1,SK);
  r(44,20,4,12,SH); r(52,20,4,12,SH); r(40,20,4,12,SH); r(48,20,4,12,SH);
  r(44,16,4,4,SK); r(48,16,4,4,SK);
  r(44,29,4,3,SK); r(40,29,4,3,SK); r(48,29,4,3,SK); r(52,29,4,3,SK);
  r(4,20,4,12,PA); r(12,20,4,12,PA); r(0,20,4,12,PA); r(8,20,4,12,PA);
  r(4,16,4,4,PA); r(8,16,4,4,PA);
  r(4,31,4,1,Shoe); r(0,31,4,1,Shoe); r(8,31,4,1,Shoe); r(12,31,4,1,Shoe);
  var t=gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D,t);
  gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,C);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
  skinT=t; return t;
}

/* ---------- 方块部件（像素单位建，画的时候整体乘 PX） ---------- */
function pcU(u,v,w,h){ return [u/64,v/64,(u+w)/64,(v+h)/64]; }
function pcPart(x0,x1,y0,y1,z0,z1,f){
  var buf=[];
  function v(x,y,z,nx,ny,nz,u,vv){ buf.push(x,y,z,nx,ny,nz,u,vv,1,1,1,7.0); }
  function quad(q,n,uv){
    v(q[0][0],q[0][1],q[0][2],n[0],n[1],n[2],uv[0],uv[3]);
    v(q[1][0],q[1][1],q[1][2],n[0],n[1],n[2],uv[2],uv[3]);
    v(q[2][0],q[2][1],q[2][2],n[0],n[1],n[2],uv[2],uv[1]);
    v(q[0][0],q[0][1],q[0][2],n[0],n[1],n[2],uv[0],uv[3]);
    v(q[2][0],q[2][1],q[2][2],n[0],n[1],n[2],uv[2],uv[1]);
    v(q[3][0],q[3][1],q[3][2],n[0],n[1],n[2],uv[0],uv[1]);
  }
  if(f.front) quad([[x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]],[0,0,1],f.front);
  if(f.back)  quad([[x1,y0,z0],[x0,y0,z0],[x0,y1,z0],[x1,y1,z0]],[0,0,-1],f.back);
  if(f.left)  quad([[x0,y0,z0],[x0,y0,z1],[x0,y1,z1],[x0,y1,z0]],[-1,0,0],f.left);
  if(f.right) quad([[x1,y0,z1],[x1,y0,z0],[x1,y1,z0],[x1,y1,z1]],[1,0,0],f.right);
  if(f.top)   quad([[x0,y1,z1],[x1,y1,z1],[x1,y1,z0],[x0,y1,z0]],[0,1,0],f.top);
  if(f.bottom)quad([[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1]],[0,-1,0],f.bottom);
  var vao=gl.createVertexArray(), vb=gl.createBuffer();
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER,vb);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(buf),gl.STATIC_DRAW);
  bindAttribs(progMain);
  gl.bindVertexArray(null);
  return {vao:vao,count:buf.length/12};
}
var avParts=null;
function buildAvatar(){
  if(avParts) return avParts;
  var head=pcU(8,8,8,8), hb=pcU(24,8,8,8), hl=pcU(16,8,8,8), hr=pcU(0,8,8,8), ht=pcU(8,0,8,8), hbot=pcU(16,0,8,8);
  var bf=pcU(20,20,8,12), bb=pcU(32,20,8,12), bl=pcU(28,20,4,12), br=pcU(16,20,4,12), bt=pcU(20,16,8,4), bbot=pcU(28,16,8,4);
  var af=pcU(44,20,4,12), ab=pcU(52,20,4,12), al=pcU(48,20,4,12), ar=pcU(40,20,4,12), at=pcU(44,16,4,4), abot=pcU(48,16,4,4);
  var lf=pcU(4,20,4,12), lb=pcU(12,20,4,12), ll=pcU(8,20,4,12), lr=pcU(0,20,4,12), lt=pcU(4,16,4,4), lbot=pcU(8,16,4,4);
  avParts={
    head: {m:pcPart(-4,4,24,32,-4,4,{front:head,back:hb,left:hl,right:hr,top:ht,bottom:hbot}), p:[0,24,0]},
    body: {m:pcPart(-4,4,12,24,-2,2,{front:bf,back:bb,left:bl,right:br,top:bt,bottom:bbot}), p:[0,12,0]},
    armR: {m:pcPart(4,8,12,24,-2,2,{front:af,back:ab,left:al,right:ar,top:at,bottom:abot}), p:[6,24,0]},
    armL: {m:pcPart(-8,-4,12,24,-2,2,{front:af,back:ab,left:al,right:ar,top:at,bottom:abot}), p:[-6,24,0]},
    legR: {m:pcPart(0,4,0,12,-2,2,{front:lf,back:lb,left:ll,right:lr,top:lt,bottom:lbot}), p:[2,12,0]},
    legL: {m:pcPart(-4,0,0,12,-2,2,{front:lf,back:lb,left:ll,right:lr,top:lt,bottom:lbot}), p:[-2,12,0]}
  };
  return avParts;
}
function pcPartMat(root,p,ang){
  var m=m4mul(m4T(p[0],p[1],p[2]),m4Rx(ang));
  m=m4mul(m,m4T(-p[0],-p[1],-p[2]));
  return m4mul(root,m);
}
function drawNetAvatars(p,eye){
  var ids=Object.keys(NETPC.players);
  if(!ids.length) return;
  var A=buildAvatar();
  var tex=mkSkin();
  gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D,tex);
  gl.activeTexture(gl.TEXTURE3); gl.bindTexture(gl.TEXTURE_2D,texNorm);
  var t=(performance.now()-T0)/1000;
  for(var i=0;i<ids.length;i++){
    var pl=NETPC.players[ids[i]];
    if(!pl||pl.sid===NETPC.sid) continue;
    /* 位置做一点插值，别人走起来不会一顿一顿 */
    pl.x+=(pl.tx-pl.x)*0.22; pl.z+=(pl.tz-pl.z)*0.22;
    if(!pl.init){ pl.x=pl.tx; pl.z=pl.tz; pl.init=1; }
    var yaw=pl.yaw||0, c=Math.cos(yaw), sn=Math.sin(yaw), yy=pl.ty-1.68;
    var root=new Float32Array([c*PX,0,-sn*PX,0, 0,PX,0,0, sn*PX,0,c*PX,0, pl.x,yy,pl.z,1]);
    var sw=Math.sin((pl.walk||0)*1.9)*0.62;
    var pit=Math.max(-0.5,Math.min(0.5,pl.pitch||0));
    var list=[["body",0],["head",-pit],["armR",-sw],["armL",sw],["legR",sw],["legL",-sw]];
    for(var k=0;k<list.length;k++){
      var part=A[list[k][0]];
      gl.uniformMatrix4fv(p.u.uM,false,pcPartMat(root,part.p,list[k][1]));
      gl.bindVertexArray(part.m.vao);
      gl.drawArrays(gl.TRIANGLES,0,part.m.count);
    }
  }
  gl.bindVertexArray(null);
}

/* ---------- MQTT 客户端（手写最小实现） ---------- */
function pcCat(){
  var o=[];
  for(var i=0;i<arguments.length;i++){
    var a=arguments[i];
    if(a&&typeof a!=="string"&&a.length!==undefined){ for(var j=0;j<a.length;j++) o.push(a[j]); }
    else o.push(a);
  }
  return o;
}
function pcUtf8(str){
  var b=[];
  for(var i=0;i<str.length;i++){
    var c=str.charCodeAt(i);
    if(c<128) b.push(c);
    else if(c<2048) b.push(192|(c>>6),128|(c&63));
    else b.push(224|(c>>12),128|((c>>6)&63),128|(c&63));
  }
  return b;
}
function pcVarint(n){
  var o=[];
  do{ var d=n%128; n=Math.floor(n/128); if(n>0) d|=128; o.push(d); }while(n>0);
  return o;
}
function pcSend(arr){ NETPC.tx=(NETPC.tx||0)+1; NETPC.lastTx=performance.now(); try{ NETPC.ws.send(new Uint8Array(arr)); }catch(e){} }
function pcPub(obj){
  if(!NETPC.ok||!NETPC.ws) return false;
  var t=pcUtf8(NETPC.topic), p=pcUtf8(JSON.stringify(obj));
  var body=pcCat([t.length>>8,t.length&255],t,p);
  pcSend(pcCat([0x30],pcVarint(body.length),body));
  return true;
}
function pcPaintChip(){
  var c=document.getElementById("netchip");
  if(!c) return;
  if(NETPC.on){
    var n=Object.keys(NETPC.players).length;
    c.innerHTML=(NETPC.room==="LOBBY"?"公共池":"房号 <b>"+NETPC.room+"</b>")+(n>0?" · <b>"+n+"</b> 人":"");
  } else {
    c.textContent=NETPC.room?("重连中… "+(NETPC.retries||1)):"单机";
  }
}
function pcCopy(){
  if(!NETPC.on){ toast("还没联机 · 点开场页的「联机开房」"); return; }
  var txt=(NETPC.room==="LOBBY")
    ? "池核 · 公共池（谁打开都进同一个池子）：https://hhh.l2.ink/games/2040k/poolcore.html"
    : ("池核 私房 "+NETPC.room+" · 直接进：https://hhh.l2.ink/games/2040k/poolcore.html?room="+NETPC.room);
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(txt).then(function(){ toast("房号 "+NETPC.room+" 已复制"); },
        function(){ toast("房号 "+NETPC.room+"（浏览器拦了复制，手抄一下）"); });
      return;
    }
  }catch(e){}
  toast("房号 "+NETPC.room);
}
function netConnect(asHost,code){
  NETPC.host=asHost; NETPC.room=code; NETPC.ok=false;
  NETPC.topic=pcTopic(code);
  NETPC.gen=(NETPC.gen||0)+1;
  var gen=NETPC.gen;
  /* 换连接前先把旧 socket 彻底掐掉，且让它的 onclose 失效，
     否则旧连接的关闭事件会把刚建好的新连接又打回“单机” */
  if(NETPC.retryT){ clearTimeout(NETPC.retryT); NETPC.retryT=null; }
  if(NETPC.ws){
    try{ NETPC.ws.onopen=NETPC.ws.onclose=NETPC.ws.onerror=null; NETPC.ws.close(); }catch(e){}
    NETPC.ws=null;
  }
  var cid="rtsxpool"+pcRand();
  /* keepalive 300s：手机/后台标签页里 setInterval 会被限流，60s 的窗口太容易超 */
  var body=pcCat([0x00,0x04],[0x4d,0x51,0x54,0x54],[0x04,0x02,0x01,0x2c],[0,cid.length],pcUtf8(cid));
  var pkt=pcCat([0x10],pcVarint(body.length),body);
  var ws;
  try{ ws=new WebSocket("wss://broker.hivemq.com:8884/mqtt","mqtt"); }
  catch(e){ toast("中继开不起来："+e.message); pcRetryNow(); return; }
  NETPC.ws=ws;
  ws.binaryType="arraybuffer";
  NETPC.connack=false;
  ws.onopen=function(){
    if(gen!==NETPC.gen) return;
    pcSend(pkt);
    var t=pcUtf8(NETPC.topic);
    var sub=pcCat([0x00,0x01,t.length>>8,t.length&255],t,[0x00]);
    pcSend(pcCat([0x82],pcVarint(sub.length),sub));
    NETPC.ok=true;
    NETPC.on=true;
    NETPC.retries=0;
    NETPC.lastTx=performance.now();
    clearInterval(NETPC.ka);
    NETPC.ka=setInterval(function(){ if(gen!==NETPC.gen) return; try{ pcSend([0xC0,0x00]); }catch(e){} },20000);
    pcPaintChip();
    toast(code==="LOBBY"?"公共池 · 所有人都在同一个池子里，等别人进来就行":("私房 "+code+" · 把链接发朋友"));
    /* 进池先喊一声，池里已经有人就会把拉杆/破洞状态回给你 */
    NETPC.joined=false;
    pcPub({t:"hello",sid:NETPC.sid,n:NETNAME});
    var n=0;
    clearInterval(NETPC.helloTimer);
    NETPC.helloTimer=setInterval(function(){
      if(gen!==NETPC.gen||NETPC.joined||++n>6){ clearInterval(NETPC.helloTimer); NETPC.helloTimer=null; return; }
      pcPub({t:"hello",sid:NETPC.sid,n:NETNAME});
    },1600);
  };
  function down(ev){
    if(gen!==NETPC.gen) return;
    NETPC.ok=false; NETPC.on=false; NETPC.connack=false;
    clearInterval(NETPC.ka); NETPC.ka=null;
    NETPC.players={};
    pcPaintChip();
    pcRetryNow(ev&&ev.type==="error"?400:0);
  }
  ws.onclose=down;
  ws.onerror=down;
  ws.onmessage=pcRecv;
}

/* 断线重连：1.5s 起，指数退避到 9s，只要还在游戏里就一直试 */
function pcRetryNow(delay){
  if(NETPC.retryT) return;
  var n=(NETPC.retries=(NETPC.retries||0)+1);
  var d=(typeof delay==="number")?delay:Math.min(9000,900*Math.pow(1.7,n-1));
  pcPaintChip();
  NETPC.retryT=setTimeout(function(){
    NETPC.retryT=null;
    if(!NETPC.room) return;
    netConnect(true,NETPC.room);
  }, d);
}
function pcRecv(e){
  var arr=new Uint8Array(e.data), type=arr[0]>>4, p=1, len=0, mul=1, d;
  do{ d=arr[p++]; len+=(d&127)*mul; mul*=128; }while(d&128);
  if(type===2){ NETPC.connack=true; NETPC.rxk=(NETPC.rxk||0)+1; return; }
  if(type!==3) return;
  NETPC.rx=(NETPC.rx||0)+1;
  var tl=(arr[p]<<8)|arr[p+1]; p+=2+tl;
  var txt=""; try{ txt=new TextDecoder("utf-8").decode(arr.subarray(p)); }catch(err){ return; }
  var m; try{ m=JSON.parse(txt); }catch(err){ return; }
  netOnMsg(m);
}
function netOnMsg(m){
  if(!m||!m.t) return;
  if(m.sid===NETPC.sid) return;
  if(m.t==="hello"){
    if(NETPC.host){
      var pulled=[];
      for(var i=0;i<levers.length;i++) if(levers[i].pulled) pulled.push(levers[i].id);
      var hs=holes.slice(-16).map(function(h){ return [h.x,h.y,h.z,h.r]; });
      pcPub({t:"snap",to:m.sid,levers:pulled,holes:hs,host:NETPC.sid});
      pcPub({t:"p",sid:NETPC.sid,x:player.x,y:player.y,z:player.z,yaw:player.yaw,pitch:player.pitch,walk:player.step});
    }
    return;
  }
  if(m.t==="snap"&&m.to===NETPC.sid){
    NETPC.joined=true;
    clearInterval(NETPC.helloTimer); NETPC.helloTimer=null;
    if(m.levers) for(var j=0;j<m.levers.length;j++){
      for(var q=0;q<levers.length;q++) if(levers[q].id===m.levers[j]&&!levers[q].pulled){ levers[q].pulled=true; levers[q].pullT=0; pulledCount++; }
    }
    if(m.holes) for(var hh=0;hh<m.holes.length;hh++){
      var e2=m.holes[hh], dup=false;
      for(var hq=0;hq<holes.length;hq++){
        if(Math.abs(holes[hq].x-e2[0])<0.25&&Math.abs(holes[hq].y-e2[1])<0.25&&Math.abs(holes[hq].z-e2[2])<0.25){ dup=true; break; }
      }
      if(!dup) holes.push({x:e2[0],y:e2[1],z:e2[2],r:e2[3]});
    }
    updateKeyHud();
    if(pulledCount>=LEVER_N) hammerOwned=true;
    toast("已连上房主的池子 · 拉杆 "+pulledCount+"/"+LEVER_N);
    return;
  }
  if(m.t==="p"){
    NETPC.lastSee=performance.now();
    var pl=NETPC.players[m.sid];
    if(!pl){ pl=NETPC.players[m.sid]={x:m.x,z:m.z,tx:m.x,tz:m.z,y:m.y,ty:m.y,yaw:m.yaw,pitch:m.pitch,walk:m.walk||0,t0:0}; }
    pl.tx=m.x; pl.tz=m.z; pl.ty=m.y; pl.yaw=m.yaw||0; pl.pitch=m.pitch||0;
    if(m.walk!==undefined||m.walk===0) pl.walk=m.walk||0;
    pl.last=performance.now();
    pcPaintChip();
    return;
  }
  if(m.t==="lv"){
    for(var q2=0;q2<levers.length;q2++){
      if(levers[q2].id===m.id&&!levers[q2].pulled){
        levers[q2].pulled=true; levers[q2].pullT=(performance.now()-T0)/1000;
        pulledCount++; updateKeyHud(); sfx("lever");
        if(pulledCount>=LEVER_N) hammerOwned=true;
      }
    }
    return;
  }
  if(m.t==="h"){
    var hd=null;
    for(var hi2=0;hi2<holes.length;hi2++){
      var hh2=holes[hi2];
      if(Math.abs(hh2.x-m.x)<0.22&&Math.abs(hh2.y-m.y)<0.22&&Math.abs(hh2.z-m.z)<0.22){ hd=hh2; break; }
    }
    if(hd) hd.r=Math.max(hd.r,(m.r||0.4));
    else holes.push({x:m.x,y:m.y,z:m.z,r:m.r||0.4});
    spawnFrags(m.x,m.y,m.z,m.dx||0,m.dz||0);
    sfx("smash");
    return;
  }
  if(m.t==="bye"&&NETPC.players[m.sid]){ delete NETPC.players[m.sid]; pcPaintChip(); }
}
function netLever(id){ pcPub({t:"lv",id:id,sid:NETPC.sid}); }
function netHole(x,y,z,dx,dz,r){ pcPub({t:"h",x:x,y:y,z:z,dx:dx,dz:dz,r:r,sid:NETPC.sid}); }
function netTick(dt){
  var now=performance.now();
  var ids=Object.keys(NETPC.players);
  for(var i=0;i<ids.length;i++){
    var pl=NETPC.players[ids[i]];
    if(pl.last&&now-pl.last>9000){ delete NETPC.players[ids[i]]; pcPaintChip(); }
  }
  if(!NETPC.on) return;
  if(now-(NETPC.lastTx||0)>40000){ try{ pcSend([0xC0,0x00]); }catch(e){} }
  if(!NETPC.host&&now-(NETPC.lastSee||0)>14000){
    NETPC.host=true; NETPC.lastSee=now; pcPaintChip();
    pcPub({t:"hello",sid:NETPC.sid,n:NETNAME});
  }
  if(now-NETPC.lastPose>110){
    NETPC.lastPose=now;
    pcPub({t:"p",sid:NETPC.sid,x:player.x,y:player.y,z:player.z,yaw:player.yaw,pitch:player.pitch,walk:player.step});
  }
}
function netEnter(code){
  NETPC.sid=pcRand();
  var c=String(code||"").replace(/[^A-Za-z0-9]/g,"");
  var priv=(c.length>=4)?c.toUpperCase():"";
  NETPC.lastSee=performance.now();
  netConnect(true,priv||"LOBBY");
  /* 公共池没有“房主”：先当应答者，看到别人发位姿就退位；长时间没人再接管 */
  setTimeout(function(){
    if(performance.now()-NETPC.lastSee>2000) return;
    NETPC.host=false; pcPaintChip();
  },2600);
}
function startHost(){ if(!NETPC.on) netEnter(""); else toast("已经在公共池里了"); }

