window.__P=function(){
  return {x:player.x,y:player.y,z:player.z,yaw:player.yaw,pitch:player.pitch,
    net:{on:NETPC.on,host:NETPC.host,room:NETPC.room,players:Object.keys(NETPC.players).length},
    levers:pulledCount,hammer:hammerOwned,holes:holes.length,frags:frags.length,
    props:regionProps.length,ducks:duckW.length,started:started,
    tris:meshCount,lights:lights.length,walls:collWalls.length,cell:[regCX,regCZ]};
};
window.__PULL=function(){ var n=nearestLever(); if(!n.l) return false; n.l.pulled=true; n.l.pullT=(performance.now()-T0)/1000; pulledCount++; if(pulledCount>=LEVER_N){ hammerOwned=true; if(!EXIT) spawnExit(); } updateKeyHud(); try{ netLever(n.l.id); }catch(e){} return true; };
window.__EXIT=function(){ return EXIT?{x:EXIT.x,z:EXIT.z,d:Math.round(exitDist()/CELL)}:null; };
window.__PROPMOD=function(){ return propMod; };
window.__HOLELIST=function(){ return holes.map(function(h){ return {x:+h.x.toFixed(2),y:+h.y.toFixed(2),z:+h.z.toFixed(2),r:+h.r.toFixed(2)}; }); };
window.__PROPS=function(){ return regionProps.filter(function(o){return o.k==="duck"||o.k==="sign";}).map(function(o){ return {k:o.k,x:+o.x.toFixed(2),z:+o.z.toFixed(2),pk:o.pk,fall:o.fallT?1:0}; }); };
window.__PERF=function(){ return {fps:PERF.fps,rebuilds:PERF.rebuilds,rebuildMs:+PERF.rebuildMs.toFixed(1),holes:holes.length,frags:frags.length,props:regionProps.length,tris:meshCount}; };
window.__HAMMER=function(v){ hammerOwned=v!==false; updateKeyHud(); };
window.__SMASH=function(){ smash(); };
window.__MAP=function(){
  var cx=Math.floor(player.x/CELL), cz=Math.floor(player.z/CELL), rows=[];
  for(var dz=-3;dz<=3;dz++){
    var r="";
    for(var dx=-3;dx<=3;dx++){
      var x=cx+dx, z=cz+dz;
      if(dx===0&&dz===0){ r+="@"; continue; }
      r+=!cellOpen(x,z)?"#":(cellPool(x,z)===1?"~":".");
    }
    rows.push(r);
  }
  return rows.join("\n")+"\ncell "+(cx)+","+(cz);
};
window.__CAM=function(){ var c=camView(); return [c.dir[0].toFixed(2),c.dir[1].toFixed(2),c.dir[2].toFixed(2)]; };
window.__SMASHTEST=function(){ return smashTest(); };
window.__DBG=function(){
  var c=camView(), cx=Math.floor(player.x/CELL), cz=Math.floor(player.z/CELL);
  var openN=[]; var dd=[[1,0],[-1,0],[0,1],[0,-1]];
  for(var i=0;i<4;i++) openN.push([dd[i][0],dd[i][1],!!cellOpen(cx+dd[i][0],cz+dd[i][1]),!!isOpen(cx+dd[i][0],cz+dd[i][1])]);
  return {dir:[+c.dir[0].toFixed(3),+c.dir[1].toFixed(3),+c.dir[2].toFixed(3)],
          eye:[+c.eye[0].toFixed(2),+c.eye[1].toFixed(2),+c.eye[2].toFixed(2)],
          p:[+player.x.toFixed(2),+player.z.toFixed(2)], yaw:+player.yaw.toFixed(3),
          cell:[cx,cz], neighbors:openN, hammer:hammerOwned, props:regionProps.length};
};
window.__LEVERS=function(){ return levers.map(function(l){return {x:l.x,z:l.z,pulled:l.pulled}; }); };
window.__SETPLAYER=function(x,z){ player.x=x; player.z=z; };
window.__LOOK=function(yaw,pitch){ player.yaw=yaw; player.pitch=pitch; };
window.__KEYIN=function(name,v){ keysDown[name]=v?1:0; };
window.__START=function(q){ begin(q===undefined?1:q); };
window.__STARTCELL=function(){ return {x:CELL*0.5,z:CELL*0.5}; };
window.__NP=function(sid,x,z,yaw,name,pit){
  NETPC.on=true;
  NETPC.players[sid||"dbg1"]={x:x,z:z,tx:x,tz:z,y:player.y,ty:player.y,yaw:yaw||0,pitch:pit||0,walk:0,last:performance.now()};
  pcPaintChip();
  return true;
};
window.__NPCLR=function(){ NETPC.players={}; return true; };
/* 回到前台或网络恢复时，别等退避计时器，马上再连一次 */
(function(){
  function wake(){
    if(NETPC.on||!NETPC.room) return;
    /* 把退避计时器清掉，直接来一次 */
    if(NETPC.retryT){ clearTimeout(NETPC.retryT); NETPC.retryT=null; }
    NETPC.retries=0; netConnect(true,NETPC.room);
  }
  document.addEventListener("visibilitychange",function(){ if(!document.hidden) wake(); });
  window.addEventListener("focus",wake);
  window.addEventListener("online",wake);
  window.addEventListener("pageshow",wake);
})();
window.__CG=function(){ return [pcCode(),pcCode(),pcRand()]; };
window.__NETDROP=function(){ try{ NETPC.ws.close(); return true; }catch(e){ return String(e.message); } };
window.__NET=function(){
  var ws=NETPC.ws;
  return {on:NETPC.on,ok:NETPC.ok,connack:!!NETPC.connack,room:NETPC.room,topic:NETPC.topic,
    sid:NETPC.sid,rnd:Math.random(),rs:ws?ws.readyState:-1,tx:NETPC.tx||0,rx:NETPC.rx||0,rxk:NETPC.rxk||0,joined:!!NETPC.joined,
    players:Object.keys(NETPC.players).length};
};
